// Fade an LED on D9 with a knob on A0.
const int LED_PIN = 9;     // D9 has PWM (Timer1)
const int KNOB_PIN = A0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(KNOB_PIN);          // 0..1023
  int duty = map(raw, 0, 1023, 0, 255);    // 0..1023 becomes 0..255
  analogWrite(LED_PIN, duty);
  Serial.print("raw=");
  Serial.print(raw);
  Serial.print(" duty=");
  Serial.println(duty);
  delay({{p:period}});
}

